const d = $json;
const s = d.summary || {};
const vnd = n => new Intl.NumberFormat('vi-VN').format(n || 0) + '₫';

const dongDichVu = (d.top_services || []).map(x => `<tr><td>${x.name}</td><td align="right">${x.quantity}</td><td align="right">${vnd(x.revenue)}</td></tr>`).join('');
const dongPhuTung = (d.top_parts || []).map(x => `<tr><td>${x.name}</td><td align="right">${x.quantity}</td><td align="right">${vnd(x.revenue)}</td></tr>`).join('');

// Công nợ để riêng chứ không trừ ngầm vào doanh thu: hai con số trả lời hai câu hỏi
// khác nhau — "làm được bao nhiêu" và "thu về được bao nhiêu".
const html = `<h2>📊 Báo cáo doanh thu ${d.period_label}</h2>`
  + `<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse">`
  + `<tr><td>Số hoá đơn</td><td align="right"><b>${s.invoice_count || 0}</b></td></tr>`
  + `<tr><td>Doanh thu</td><td align="right"><b>${vnd(s.revenue)}</b></td></tr>`
  + `<tr><td>Đã thu</td><td align="right">${vnd(s.collected)}</td></tr>`
  + `<tr><td>Còn phải thu</td><td align="right"><b style="color:#c00">${vnd(s.outstanding)}</b></td></tr>`
  + `<tr><td>Tiền công</td><td align="right">${vnd(s.labor_revenue)}</td></tr>`
  + `<tr><td>Tiền phụ tùng</td><td align="right">${vnd(s.parts_revenue)}</td></tr>`
  + `</table>`
  + (dongDichVu ? `<h3>Hạng mục dịch vụ nhiều nhất</h3><table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse"><tr><th>Hạng mục</th><th>SL</th><th>Doanh thu</th></tr>${dongDichVu}</table>` : '')
  + (dongPhuTung ? `<h3>Phụ tùng bán nhiều nhất</h3><table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse"><tr><th>Phụ tùng</th><th>SL</th><th>Doanh thu</th></tr>${dongPhuTung}</table>` : '')
  + `<p style="color:#888;font-size:12px">${d.company_name} — ${new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' })}</p>`;

return { json: {
  email_to: d.company_email || '',
  email_subject: `📊 Doanh thu ${d.period_label}: ${vnd(s.revenue)}`,
  email_html: html
} };
